#include <tuple>
#include <iostream>

std::tuple<int, std::string> getResult() {
    // Simulate a function that computes a value and a status
    return std::make_tuple(100, "Operation successful");
}

int main() {
    auto result = getResult();  // Returns a tuple

    // Using structured bindings for readability (C++17+)
    auto [code, message] = result;
    std::cout << "Code: " << code << ", Message: " << message << std::endl;

    return 0;
}
